insert into releases (id,label,sia_collections,tap_release_filter,s3_prefix,sapm_path_template,doi,priority,is_active,released_at,notes) values ('dr1','Data Release 1',array['spherex_dr1','spherex_dr1_deep']::text[],'spherex_dr1','dr1/','dr1/solid_angle_pixel_map/cal-sapm-v3-2026-191/{k}/solid_angle_pixel_map_D{k}_spx_cal-sapm-v3-2026-191.fits','10.26131/IRSA678',20,true,'2026-11-01','Covers 2025-05 .. 2026-05 (first two full-sky passes).') on conflict (id) do nothing;
insert into releases (id,label,sia_collections,tap_release_filter,s3_prefix,sapm_path_template,doi,priority,is_active,released_at,notes) values ('qr3','Quick Release 3',array['spherex_qr3','spherex_qr3_deep']::text[],'spherex_qr3','qr3/','qr3/solid_angle_pixel_map/cal-sapm-v3-2026-191/{k}/solid_angle_pixel_map_D{k}_spx_cal-sapm-v3-2026-191.fits','10.26131/IRSA662',10,true,'2026-09-01','Newer exposures (2026-08 onward) that are not in DR1. Updated weekly.') on conflict (id) do nothing;
insert into targets (slug,name,ra_deg,dec_deg,ref_epoch,pmra_masyr,pmdec_masyr,parallax_mas,view_ra,view_dec,category,description,what_to_see,recommended_view,is_featured,sort_order) values ('barnards-star','Barnard''s Star',269.4520769586187,4.69336496657667,2000.0,-801.551,10362.394,546.9759,269.446269,4.768204,'high-pm-star','A small red dwarf only 6 light-years away. It has the largest proper motion of any star: about 10.4 arcseconds per year, so it visibly shifts between SPHEREx sky surveys.','The bright star at the centre creeps upward (north): about 0.85 pixel every six months, roughly 2 pixels between the first and last survey. Zoom in and blink, and watch it move relative to the red crosshair''s first position.','{"band": "ALL", "fov": 180, "zoom": 6, "diff": "none"}'::jsonb,true,0) on conflict (slug) do nothing;
insert into targets (slug,name,ra_deg,dec_deg,ref_epoch,pmra_masyr,pmdec_masyr,parallax_mas,view_ra,view_dec,category,description,what_to_see,recommended_view,is_featured,sort_order) values ('eps-indi-b','Epsilon Indi B (Ba/Bb)',331.04414658852124,-56.78284419511611,2000.0,3981.977,-2466.832,270.658,331.096644,-56.80066,'brown-dwarf','A pair of brown dwarfs orbiting each other, 12 light-years away, moving 4.7 arcseconds per year across the sky.','Subtle: the motion is about 0.4 pixel per six months (1.5 pixels over the 17 months of data). Try difference mode (each frame minus the first) and the D5/D6 bands where brown dwarfs are brightest.','{"band": "D6", "fov": 180, "zoom": 8, "diff": "first"}'::jsonb,true,1) on conflict (slug) do nothing;
insert into targets (slug,name,ra_deg,dec_deg,ref_epoch,pmra_masyr,pmdec_masyr,parallax_mas,view_ra,view_dec,category,description,what_to_see,recommended_view,is_featured,sort_order) values ('wise-0855','WISE 0855-0714',133.81890825,-7.247048,2000.0,-8123.7,673.2,439.0,133.759765,-7.242186,'brown-dwarf','The coldest brown dwarf known (about -25 C), 7.4 light-years away. It is almost invisible in visible and near-infrared light and glows only at 4-5 micrometres.','Switch between D1 and D6: the object is absent at short wavelengths and obvious in D6. It drifts left (west) by about 0.7 pixel every six months.','{"band": "D6", "fov": 180, "zoom": 6, "diff": "none"}'::jsonb,true,2) on conflict (slug) do nothing;
insert into targets (slug,name,ra_deg,dec_deg,ref_epoch,pmra_masyr,pmdec_masyr,parallax_mas,view_ra,view_dec,category,description,what_to_see,recommended_view,is_featured,sort_order) values ('rw-aur','RW Aurigae',76.95652603458,30.40143817389,2000.0,7.23,-20.33,15.42,76.956587,30.401291,'variable','A very young (T Tauri) star still surrounded by the disk it formed from. Its brightness changes irregularly as clumps of dust pass in front of it.','Compare the brightness of the central star between epochs, then click it to plot its light curve and spectrum.','{"band": "D2", "fov": 180, "zoom": 4, "diff": "none"}'::jsonb,true,3) on conflict (slug) do nothing;
insert into targets (slug,name,ra_deg,dec_deg,ref_epoch,pmra_masyr,pmdec_masyr,parallax_mas,view_ra,view_dec,category,description,what_to_see,recommended_view,is_featured,sort_order) values ('r-dra','R Draconis',248.16761083295,66.75497941722,2000.0,-20.643,6.149,1.2509,248.167233,66.755024,'variable','A Mira-type pulsating red giant with a period of about 245 days. Its brightness changes by a large factor over a cycle.','Blink the D1 frames: the star changes brightness strongly between epochs. Click it to see the light curve and how the spectrum changes.','{"band": "D1", "fov": 180, "zoom": 4, "diff": "none"}'::jsonb,true,4) on conflict (slug) do nothing;
insert into targets (slug,name,ra_deg,dec_deg,ref_epoch,pmra_masyr,pmdec_masyr,parallax_mas,view_ra,view_dec,category,description,what_to_see,recommended_view,is_featured,sort_order) values ('luhman-16','Luhman 16 AB',162.328814,-53.319466,2000.0,-2767.502,356.856,501.557,162.295354,-53.316889,'brown-dwarf','The closest brown dwarfs to the Sun (6.5 light-years), a bright binary moving 2.8 arcseconds per year.','A bright red source in the Brown dwarf hunter colour view; it drifts slowly between epochs.','{"band": "RGB:D2,D4,D5+D6", "fov": 180, "zoom": 6, "diff": "none"}'::jsonb,false,5) on conflict (slug) do nothing;
insert into targets (slug,name,ra_deg,dec_deg,ref_epoch,pmra_masyr,pmdec_masyr,parallax_mas,view_ra,view_dec,category,description,what_to_see,recommended_view,is_featured,sort_order) values ('nep-deep-field','North Ecliptic Pole deep field',270.0,66.56,2000.0,null,null,null,270.0,66.56,'deep-field','SPHEREx looks at the ecliptic poles on almost every orbit, so this patch has hundreds of exposures and the finest time sampling.','Use ''All exposures'' mode or a short window (1-7 days) to see the sky change on short timescales.','{"band": "ALL", "fov": 300, "zoom": 3, "diff": "none", "window": 3}'::jsonb,false,6) on conflict (slug) do nothing;
insert into targets (slug,name,ra_deg,dec_deg,ref_epoch,pmra_masyr,pmdec_masyr,parallax_mas,view_ra,view_dec,category,description,what_to_see,recommended_view,is_featured,sort_order) values ('ecliptic-field','Ecliptic plane field (asteroids)',30.0,12.23,2000.0,null,null,null,30.0,12.23,'asteroid-field','A random patch on the ecliptic, the plane where most asteroids orbit. Asteroids move so fast that they appear in single exposures only.','Use ''All exposures'' mode with D1 or ALL and look for dots that appear in only one frame.','{"band": "ALL", "fov": 300, "zoom": 3, "diff": "mean", "mode": "exposures"}'::jsonb,false,7) on conflict (slug) do nothing;
